import React from 'react';

// Este é um componente "controlado" pelo App.js
function SettingsForm({ settings, onSettingsChange }) {

  const handleChange = (e) => {
    onSettingsChange({
      ...settings,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div style={{ background: '#e9ecef', padding: '15px', borderRadius: '8px', marginBottom: '20px' }}>
      <h2>Configurações Globais</h2>
      <input
        name="iof_percent"
        type="number"
        step="0.01"
        placeholder="IOF (%)"
        value={settings.iof_percent}
        onChange={handleChange}
      />
      <input
        name="taxa_dolar"
        type="number"
        step="0.01"
        placeholder="Cotação Dólar (R$)"
        value={settings.taxa_dolar}
        onChange={handleChange}
      />
    </div>
  );
}

export default SettingsForm;
